import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"结构型模式 (Structural Patterns)","description":"","frontmatter":{},"headers":[],"relativePath":"structural/overview.md","filePath":"structural/overview.md","lastUpdated":1791593259000}`),a={name:`structural/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="结构型模式-structural-patterns" tabindex="-1">结构型模式 (Structural Patterns) <a class="header-anchor" href="#结构型模式-structural-patterns" aria-label="Permalink to “结构型模式 (Structural Patterns)”">​</a></h1><p><strong>主要解决的问题</strong>：类和对象的组合方式。这类模式通过不同方式组合对象，以形成更大的结构。 结构型模式关注如何把类和对象组合成更大的结构，同时保持结构的灵活与高效。它们主要通过继承与组合两种手段，在不改变现有代码的前提下为系统增加新的能力。</p><h3 id="本目录包含的模式" tabindex="-1">本目录包含的模式 <a class="header-anchor" href="#本目录包含的模式" aria-label="Permalink to “本目录包含的模式”">​</a></h3><ul><li><a href="/hello-design-patterns/structural/adapter">适配器模式</a>：把一个类的接口转换成客户端期望的另一个接口，使原本不兼容的类可以协同工作。</li><li><a href="/hello-design-patterns/structural/decorator">装饰模式</a>：动态地为对象添加职责，而不改变其接口。</li><li><a href="/hello-design-patterns/structural/proxy">代理模式</a>：为其他对象提供代理以控制对它的访问。</li><li><a href="/hello-design-patterns/structural/virtual-proxy">虚拟代理模式</a>：延迟创建开销大的对象，直到真正需要时才实例化。</li><li><a href="/hello-design-patterns/structural/protection-proxy">保护代理模式</a>：根据访问权限控制对真实对象的访问。</li><li><a href="/hello-design-patterns/structural/remote-proxy">远程代理模式</a>：为不同地址空间中的对象提供本地代表，隐藏远程通信细节。</li><li><a href="/hello-design-patterns/structural/dynamic-proxy">动态代理模式</a>：在运行时生成代理类，统一处理日志、事务等横切关注点。</li><li><a href="/hello-design-patterns/structural/smart-pointer">智能指针模式</a>：以智能指针的形式在访问对象时附加额外操作，并自动管理资源。</li><li><a href="/hello-design-patterns/structural/facade">外观模式</a>：为子系统中的一组接口提供一个统一的高层接口，简化子系统的使用。</li><li><a href="/hello-design-patterns/structural/remote-facade">远程外观与数据传输对象</a>：跨进程边界不放领域对象，放按用例切分的粗粒度接口与专用传输对象。</li><li><a href="/hello-design-patterns/structural/bridge">桥接模式</a>：将抽象部分与实现部分分离，使二者可以独立变化。</li><li><a href="/hello-design-patterns/structural/bidirectional-bridge">双向桥接模式</a>：在桥接的基础上支持两个层次结构之间的双向通信。</li><li><a href="/hello-design-patterns/structural/composite">组合模式</a>：将对象组合成树形结构表示&quot;部分-整体&quot;的层次，使客户端一致地使用单个对象与组合对象。</li><li><a href="/hello-design-patterns/structural/flyweight">享元模式</a>：通过共享细粒度对象来支持大量对象，减少内存占用。</li><li><a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>：由外部容器提供对象所需的依赖，实现对象之间的解耦。</li></ul><h3 id="选用建议" tabindex="-1">选用建议 <a class="header-anchor" href="#选用建议" aria-label="Permalink to “选用建议”">​</a></h3><ul><li>接口不兼容时用适配器；接口太复杂时用外观；接口要跨进程时用远程外观加 DTO，别把细粒度对象接口摆上网络。</li><li>需要控制访问、延迟加载或附加额外行为时，选择代理及其变体。</li><li>需要动态叠加行为时用装饰，而不是创建大量子类。</li><li>存在多个独立变化维度时用桥接；存在大量相似对象时考虑享元。</li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};